/**
 * The one error a desktop front end sees. Seven cases, each with a typed
 * reason to branch on; `message` is diagnostic English for a details view
 * or tooltip, never primary copy.
 */
public 
enum DesktopError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotSignedIn(message: String
    )
    case DaemonUnavailable(message: String, reason: DaemonUnavailableReason
    )
    case Network(message: String, kind: NetworkErrorKind
    )
    case PermissionDenied(message: String, reason: PermissionDeniedReason
    )
    /**
     * Refused because a folder group would be left without a confirmed
     * complete copy. `can_force` says whether calling again with `force`
     * is offered for this operation.
     */
    case DurabilityBlocked(message: String, groupIds: [String], operationId: String?, canForce: Bool
    )
    case InvalidInput(message: String, field: String?
    )
    case Internal(message: String, category: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

