    typealias SwiftType = LoginEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LoginEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .enrolling
        
        case 2: return .openBrowser(url: try FfiConverterString.read(from: &buf), purpose: try FfiConverterTypeBrowserPurpose.read(from: &buf)
        )
        
        case 3: return .waitingForApproval(expiresIn: try FfiConverterDuration.read(from: &buf)
        )
        
        case 4: return .waitingForAuthorization
        
        case 5: return .showDeviceCode(verificationUri: try FfiConverterString.read(from: &buf), userCode: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .signedIn(account: try FfiConverterTypeAccountStatus.read(from: &buf)
        )
        
        case 7: return .failed(error: try FfiConverterTypeDesktopError.read(from: &buf)
        )
        
        case 8: return .cancelled
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LoginEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .enrolling:
            writeInt(&buf, Int32(1))
        
        
        case let .openBrowser(url,purpose):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(url, into: &buf)
            FfiConverterTypeBrowserPurpose.write(purpose, into: &buf)
            
        
        case let .waitingForApproval(expiresIn):
            writeInt(&buf, Int32(3))
            FfiConverterDuration.write(expiresIn, into: &buf)
            
        
        case .waitingForAuthorization:
            writeInt(&buf, Int32(4))
        
        
