            FfiConverterString.write(verificationUri, into: &buf)
            FfiConverterString.write(userCode, into: &buf)
            
        
        case let .signedIn(account):
            writeInt(&buf, Int32(6))
            FfiConverterTypeAccountStatus.write(account, into: &buf)
            
        
        case let .failed(error):
            writeInt(&buf, Int32(7))
            FfiConverterTypeDesktopError.write(error, into: &buf)
            
        
