/**
 * One risky condition a link preflight found, in the order the preflight
 * reports them.
 */

public enum PreflightIssue: Equatable, Hashable {
    
    case pathMissing
    case ignoreRulesUnreadable
    case notEmpty(entryCount: UInt64, scanTruncated: Bool
    )
    case lowFreeSpace(availableBytes: UInt64, headroomBytes: UInt64
    )
    case criticalFreeSpace(availableBytes: UInt64, headroomBytes: UInt64
    )
    case nestedLink(otherPath: String, relation: NestedLinkRelation
    )
    case cloudProviderFolder(provider: String
    )
    case filesystemRoot
    case homeDirectory
    case reservedName(path: String
    )





}

#if compiler(>=6)
extension PreflightIssue: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePreflightIssue: FfiConverterRustBuffer {
    typealias SwiftType = PreflightIssue

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PreflightIssue {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pathMissing
        
        case 2: return .ignoreRulesUnreadable
        
        case 3: return .notEmpty(entryCount: try FfiConverterUInt64.read(from: &buf), scanTruncated: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .lowFreeSpace(availableBytes: try FfiConverterUInt64.read(from: &buf), headroomBytes: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 5: return .criticalFreeSpace(availableBytes: try FfiConverterUInt64.read(from: &buf), headroomBytes: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 6: return .nestedLink(otherPath: try FfiConverterString.read(from: &buf), relation: try FfiConverterTypeNestedLinkRelation.read(from: &buf)
        )
        
        case 7: return .cloudProviderFolder(provider: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .filesystemRoot
        
        case 9: return .homeDirectory
        
        case 10: return .reservedName(path: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PreflightIssue, into buf: inout [UInt8]) {
        switch value {
        
        
        case .pathMissing:
            writeInt(&buf, Int32(1))
        
        
        case .ignoreRulesUnreadable:
            writeInt(&buf, Int32(2))
        
        
        case let .notEmpty(entryCount,scanTruncated):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(entryCount, into: &buf)
            FfiConverterBool.write(scanTruncated, into: &buf)
            
        
        case let .lowFreeSpace(availableBytes,headroomBytes):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(availableBytes, into: &buf)
            FfiConverterUInt64.write(headroomBytes, into: &buf)
            
        
        case let .criticalFreeSpace(availableBytes,headroomBytes):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(availableBytes, into: &buf)
            FfiConverterUInt64.write(headroomBytes, into: &buf)
            
        
        case let .nestedLink(otherPath,relation):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(otherPath, into: &buf)
            FfiConverterTypeNestedLinkRelation.write(relation, into: &buf)
            
        
        case let .cloudProviderFolder(provider):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(provider, into: &buf)
            
        
        case .filesystemRoot:
            writeInt(&buf, Int32(8))
        
        
        case .homeDirectory:
            writeInt(&buf, Int32(9))
        
        
        case let .reservedName(path):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(path, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePreflightIssue_lift(_ buf: RustBuffer) throws -> PreflightIssue {
    return try FfiConverterTypePreflightIssue.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePreflightIssue_lower(_ value: PreflightIssue) -> RustBuffer {
    return FfiConverterTypePreflightIssue.lower(value)
}




